-- Biblioteca Inclusiva · Geografia do 9º ano completa.
WITH lessons(code,title,goal) AS (VALUES
('EF09GE01','Da bipolaridade à multipolaridade','Analisar mudanças da ordem mundial por atores, alianças, redes e diferentes escalas.'),
('EF09GE02','Poder e nova ordem mundial','Comparar dimensões econômica, política, militar, tecnológica e cultural do poder global.'),
('EF09GE03','Corporações e organismos mundiais','Avaliar como corporações e organismos econômicos influenciam decisões e territórios.'),
('EF09GE04','Manifestações culturais e minorias','Reconhecer diversidade cultural e reivindicações por direitos sem expor identidades pessoais.'),
('EF09GE05','Europa e Ásia na ordem mundial','Comparar papéis e interdependências de países e blocos europeus e asiáticos.'),
('EF09GE06','Integração europeia','Analisar formação, funcionamento, potencialidades e tensões da integração europeia.'),
('EF09GE07','Europa: economia, política e população','Relacionar redes econômicas, dinâmicas populacionais e desigualdades territoriais europeias.'),
('EF09GE08','Espaço pós-soviético','Analisar fragmentação territorial, redes e relações de poder no espaço pós-soviético.'),
('EF09GE09','Rússia e Leste Europeu','Comparar fatores energéticos, econômicos e geopolíticos no Leste Europeu com fontes atualizadas.'),
('EF09GE10','Ascensão chinesa','Explicar transformações econômicas e territoriais ligadas à ascensão chinesa.'),
('EF09GE11','Redes e disputas tecnológicas','Analisar infraestrutura, comércio e tecnologia nas relações entre China, Ásia e mundo.'),
('EF09GE12','Oriente Médio e recursos estratégicos','Relacionar fronteiras, petróleo, água e redes de poder com abordagem informativa e não gráfica.'),
('EF09GE13','Diversidade e geopolítica do Oriente Médio','Analisar diversidade cultural, religiosa e política sem reduzir grupos a conflitos ou estereótipos.'),
('EF09GE14','Produção agropecuária europeia e asiática','Comparar sistemas agropecuários por fatores naturais, tecnologia, políticas e relações de trabalho.'),
('EF09GE15','Industrialização europeia e asiática','Relacionar indústria, energia, inovação, redes urbanas, trabalho e impactos ambientais.'),
('EF09GE16','Globalização e impactos ambientais','Analisar impactos ambientais globais, responsabilidades diferenciadas e escalas de ação.'),
('EF09GE17','Acordos e sustentabilidade global','Avaliar acordos climáticos e soluções por evidência, equidade, viabilidade e governança.'),
('EF09GE18','Cartografia da Europa, Ásia e Oceania','Interpretar mapas temáticos e anamorfoses sem confundir variável representada com área territorial.')
), normalized AS (
 SELECT code,'src/escola-brilha/curso-v4/geografia-9ano/dados-fund2.ts'::text AS source_key,title,goal FROM lessons
)
