SELECT source_key,'audit-2026-09-04',code,title,'fundamental_2','9º Ano','Geografia',title,goal,ARRAY['tea','tdah','dislexia','deficiencia_intelectual','comunicacao','motora_escrita'],
jsonb_build_array(jsonb_build_object('title','Guia de síntese geopolítica — '||code,'purpose',goal,'sections',jsonb_build_array(
 jsonb_build_object('heading','Prepare fontes atuais, plurais e seguras','content',jsonb_build_array('Use mapas, gráficos, documentos e dados públicos agregados de instituições identificadas; nunca peça religião, etnia, nacionalidade, renda, posicionamento político, endereço, geolocalização ou história familiar do estudante.','Guerra Fria, colonialismo, migrações, extremismo, disputas e conflitos atuais devem ser abordados historicamente, de modo informativo e não gráfico, sem encenação, simulação estratégica ou atribuição de culpa coletiva.')),
 jsonb_build_object('heading','Evite simplificações culturais e geopolíticas','content',jsonb_build_array('Não reduza povos, religiões, minorias, Europa, Ásia, Oriente Médio ou Oceania a blocos homogêneos; mostre diversidade interna, agência, direitos e mudanças no tempo.','Diferencie descrição, interpretação e julgamento; sinalize quando dados ou alianças podem ter mudado e exija data e fonte.')),
 jsonb_build_object('heading','Modele a síntese multicausal','content',jsonb_build_array('Verifique autoria, instituição, data, recorte, escala, variável, método e interesse; triangule ao menos duas fontes quando houver controvérsia.','Construa matriz de atores, interesses, recursos, redes, escalas, causas e consequências; teste explicações alternativas e reconheça incertezas.','Mapas, anamorfoses e gráficos devem combinar cor com rótulo, forma, textura, contorno ou padrão e oferecer descrição textual, tabela equivalente ou alternativa tátil.')),
 jsonb_build_object('heading','Rotina adaptativa e critério','content',jsonb_build_array('Segmente textos densos, antecipe vocabulário, revele dados em camadas, dê uma instrução por vez e ofereça pistas graduadas e pausa.','Aceite fala, apontamento, cartões, mapa, tabela, gráfico, linha do tempo, matriz de atores, mapa conceitual, áudio, digitação, escrita ou tecnologia assistiva.','Critério: resolve quatro de cinco situações e sustenta três conclusões triangulando fontes, escalas, atores e evidências.'))))),
jsonb_build_array(jsonb_build_object('title','1. Delimitar e verificar','instruction','Defina questão, período, território, escala e conceitos; verifique autoria, data, método e propósito.','activity','Registre duas evidências, uma divergência e uma informação que precisa ser atualizada.','support','Glossário, texto segmentado, leitura mediada e fonte ampliada, descrita ou tabular.'),jsonb_build_object('title','2. Triangular e modelar','instruction','Compare ao menos duas fontes e mapeie atores, interesses, redes, causas e consequências.','activity','Construa matriz de atores, mapa conceitual, gráfico acessível ou cenário comparativo sobre '||lower(title)||'.','support','Exemplo resolvido, dados em camadas e pistas graduadas.'),jsonb_build_object('title','3. Sintetizar e avaliar','instruction','Apresente tese, evidências convergentes e divergentes, alternativa e grau de incerteza.','activity','Avalie uma proposta por direitos, impacto, escala, viabilidade, equidade, governança e efeitos indiretos.','support','Resposta oral, apontada, esquemática, gravada, digitada, escrita ou assistida.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Delimita questão e identifica evidências, divergência e necessidade de atualização.'),jsonb_build_object('page',2,'answer','Triangula fontes e representa relações sem atribuir culpa coletiva.'),jsonb_build_object('page',3,'answer','Síntese sustentada, incerteza explícita e proposta avaliada por critérios.','teacher_note','Registre raciocínio, autonomia, apoio eficaz e próximo passo; não registre identidade, religião, localização, renda ou opinião política pessoal.')),
